def createDefaultAdmin(apps, schemaEditor):
    """Cria o administrador padrão quando o banco está vazio (R03)."""
    # Dentro de migration usamos o modelo "histórico" via apps.get_model
    User = apps.get_model(*settings.AUTH_USER_MODEL.split("."))
    Profile = apps.get_model("accounts", "Profile")


    username = os.environ.get("COLECTURE_ADMIN_USERNAME", "admin")
    email = os.environ.get("COLECTURE_ADMIN_EMAIL", "admin@colecture.com")
    password = os.environ.get("COLECTURE_ADMIN_PASSWORD", "Admin#Colecture2026")

    # Se já existe, não faz nada (evita duplicar ao rodar migrate de novo).
    if User.objects.filter(username=username).exists():
        return

    admin = User.objects.create(
        username=username,
        email=email,
        # O modelo histórico não tem create_superuser/set_password,
        # então geramos o hash da senha manualmente.
        password=make_password(password),
        is_staff=True,
        is_superuser=True,
        is_active=True,
    )

    # O Profile normalmente só é criado no cadastro (register_view).
    # Sem isto, o admin ficaria sem perfil e quebraria as sprints futuras
    # exemplo: Ofensiva
    Profile.objects.create(user=admin)

def removeDefaultAdmin(apps, schemaEditor):
    """Desfaz o seed (usado em migrate accounts 0001)."""
    User = apps.get_model(*settings.AUTH_USER_MODEL.split("."))
    username = os.environ.get("COLECTURE_ADMIN_USERNAME", "admin")
    User.objects.filter(username=username, is_superuser=True).delete()


